const DATA = {"series":[{"name":"BLAKE3","min":[0.7234701335368499,0.722676861537029,0.7134461545658682,0.7085803234420174,0.7031370762056883,0.712134672694693,0.38698110516151685,0.37837191827282934,0.38239871452151725,0.37721792856852215,0.3738359263245489,0.3781636555989583,0.3728025099810432,0.37458490070543793,0.3760082456800673],"med":[0.770256903087779,0.7755141729778385,0.7693645911302396,0.7609776751057393,0.7559871815102019,0.7770337837408499,0.41056536385182585,0.4057741972806619,0.4010633475049979,0.393827756245931,0.3930414763974472,0.39625590006510414,0.3967144910026999,0.39452633104826274,0.3939027786254883],"max":[0.8513521544389951,0.8513575970730648,0.8585661489520958,0.8252261601215333,0.8147246383578937,0.8601017626575844,0.5095086464185393,0.45175069086158043,0.47602797999526514,0.438884523179796,0.4365007642289282,0.4407459513346354,0.4698669209199793,0.4474363828960218,0.44027964274088544]},{"name":"SHA-256","min":[0.48258081678705295,0.3785329367449608,0.3427595889091791,0.3392853571047578,0.33821103545464126,0.3392390958602284,0.33808216908919725,0.33728442019970806,0.33836253530430027,0.33724456518626283,0.3370039302147239,0.3373594169157097,0.33733321399223515,0.3375923759058902,0.3376126289367676],"med":[0.5081072050081411,0.39530350893428,0.3601399883549234,0.3576835695807553,0.35468048266120533,0.35470694397033264,0.35279524390283223,0.35206084578744246,0.3530874446946748,0.35128403828640486,0.3498697573421923,0.3507530028561512,0.349792992196432,0.3486620752434981,0.34734010696411133],"max":[0.6686994937767043,0.44358881805868694,0.4073399426127771,0.4159428047325048,0.40827298970735426,0.3989084222939424,0.3931389531959348,0.3938955859098549,0.4204434319765853,0.3925446541078629,0.40242715847272814,0.42197602053722705,0.43698445762076027,0.416052968878495,0.42412281036376953]},{"name":"SHA-1DC","min":[2.702990230593205,1.8497602903189578,1.478915023982218,1.2853814671630392,1.1833245247329602,1.1558846383815624,1.1567259576440996,1.1458851473508693,1.1613319502448156,1.1762724941216627,1.1758998948700574,1.2017618815104167,1.262650576504794,1.2674331665039063,1.2828509012858074],"med":[2.960534108578302,2.0347979723532497,1.6215111996227187,1.3848308783171057,1.2741769588207867,1.245571495987508,1.2367323059664903,1.228521626058528,1.2128041350896457,1.2392210728913835,1.2393809727260043,1.2786256472269695,1.307790929620916,1.340064525604248,1.368178367614746],"max":[3.4051425071877017,2.162924785676849,1.759461277491811,1.623859744893089,1.442063252373686,1.4073729542220115,1.4733646908040587,1.2847754023343825,1.3920538414458525,1.32034183242946,1.3385694854113521,1.4263391494750977,1.4693086797540837,1.4781554539998372,1.5496282577514648]},{"name":"BLAKE3 SME2","min":[0.7355601564902173,0.7412785288438863,0.7271928755098421,0.7004623511108137,0.6911917505322837,0.7612723155962584,0.39858602161843876,0.3885372038810484,0.23176261251286945,0.21427351035190942,0.20358235540996025,0.19090106440525428,0.17789444742323476,0.17637805938720702,0.17519397735595704],"med":[0.820373692206237,0.7910269094151633,0.7715990202163504,0.7646646438369914,0.757662795231729,0.8059940401925689,0.42374570426410385,0.41082030265562,0.2346556316050448,0.2161752216345887,0.20573956033457882,0.19833309198516647,0.1850259032430528,0.17955799102783204,0.1782059669494629],"max":[0.8777731195281019,0.894827178030303,0.8421264944286813,0.8875409863490364,0.8832469146118043,0.9660836414349916,0.5274516362788807,0.45508511450982864,0.24341861222141473,0.22130437007382328,0.21506895747870505,0.20263811497906453,0.19467230688167525,0.1927952289581299,0.19267005920410157]}],"x":[150.00,207.86,265.71,323.57,381.43,439.29,497.14,555.00,612.86,670.71,728.57,786.43,844.29,902.14,960.00],"labelY":[342.86,386.86,241.01,430.86],"sizes":["64 B","128 B","256 B","512 B","1 KiB","2 KiB","4 KiB","8 KiB","16 KiB","32 KiB","64 KiB","128 KiB","256 KiB","512 KiB","1 MiB"],"baseline":0,"sharedProv":6,"plotLeft":110,"plotRight":1000,"plotTop":135,"plotBottom":455,"labelGap":44,"parkGap":22,"provTop":540,"provLine":14,"takeaway":"On this machine: SHA-256 is 1.12× to 2.19× faster than BLAKE3; BLAKE3 is 1.60× to 3.84× faster than SHA-1DC; BLAKE3 is faster at 64 B, BLAKE3 SME2 at 1 MiB"};

const on = DATA.series.map(() => true);
const NS = "http://www.w3.org/2000/svg";

function niceBelow(v) {
  const mag = Math.pow(10, Math.floor(Math.log10(v)));
  const n = v / mag;
  return (n >= 5 ? 5 : n >= 2 ? 2 : 1) * mag;
}
function niceAbove(v) {
  const mag = Math.pow(10, Math.floor(Math.log10(v)));
  const n = v / mag;
  return (n <= 1 ? 1 : n <= 2 ? 2 : n <= 5 ? 5 : 10) * mag;
}
function fmtTick(v) {
  return v >= 10 ? v.toFixed(0) : v >= 1 ? v.toFixed(1) : v.toFixed(2);
}
function fmt2(v) { return v.toFixed(2); }
function label(i) { return DATA.sizes[i]; }

function ticks(lo, hi) {
  const out = [];
  const eLo = Math.floor(Math.log10(lo)) - 1, eHi = Math.ceil(Math.log10(hi)) + 1;
  for (let e = eLo; e <= eHi; e++) {
    for (const m of [1, 1.5, 2, 3, 5, 7]) {
      const v = m * Math.pow(10, e);
      if (v >= lo * 0.999999 && v <= hi * 1.000001) out.push(v);
    }
  }
  return out;
}

/* Mirror of takeaway_clause() in main.rs, for the visible contenders. */
function clause(i) {
  const b = DATA.series[DATA.baseline], s = DATA.series[i];
  const ratios = b.med.map((v, k) => v / s.med[k]);
  const lowest = Math.min(...ratios), highest = Math.max(...ratios);
  const TIE = 0.05, n = s.name, bn = b.name;
  const tiedLow = lowest > 1 - TIE, tiedHigh = highest < 1 + TIE;
  const x = v => v.toFixed(2) + "\u00d7";
  if (tiedLow && tiedHigh) return `${n} matches ${bn} at every size`;
  if (lowest > 1 + TIE) return `${n} is ${x(lowest)} to ${x(highest)} faster than ${bn}`;
  if (highest < 1 - TIE) return `${bn} is ${x(1 / highest)} to ${x(1 / lowest)} faster than ${n}`;
  if (tiedLow) {
    const first = ratios.findIndex(r => r > 1 + TIE);
    return `${n} matches ${bn} below ${label(first)} and is up to ${x(highest)} faster from there`;
  }
  if (tiedHigh) {
    let last = -1; ratios.forEach((r, k) => { if (r < 1 - TIE) last = k; });
    return `${bn} is up to ${x(1 / lowest)} faster than ${n} through ${label(last)}, then they match`;
  }
  const first = ratios[0] > 1 ? n : bn, lastN = ratios[ratios.length - 1] > 1 ? n : bn;
  return `${first} is faster at ${label(0)}, ${lastN} at ${label(ratios.length - 1)}`;
}

function takeaway() {
  const visible = DATA.series.map((_, i) => i).filter(i => on[i]);
  if (visible.length === 0) return "Every contender is hidden; click a name at right to show one";
  if (!on[DATA.baseline]) {
    return visible.length === 1
      ? `Showing ${DATA.series[visible[0]].name} alone`
      : `Showing ${visible.map(i => DATA.series[i].name).join(", ")}; show ${DATA.series[DATA.baseline].name} for speed ratios`;
  }
  const others = visible.filter(i => i !== DATA.baseline);
  if (others.length === 0) return `Showing ${DATA.series[DATA.baseline].name} alone`;
  return "On this machine: " + others.map(clause).join("; ");
}

function relayout() {
  const visible = DATA.series.map((_, i) => i).filter(i => on[i]);
  let lo = Infinity, hi = 0;
  for (const i of visible) {
    lo = Math.min(lo, ...DATA.series[i].min);
    hi = Math.max(hi, ...DATA.series[i].max);
  }
  if (visible.length === 0) { lo = 0.1; hi = 1; }
  const axMin = niceBelow(lo * 0.92), axMax = niceAbove(hi * 1.08);
  const lMin = Math.log(axMin), lMax = Math.log(axMax);
  const mapY = v => DATA.plotBottom - (Math.log(v) - lMin) / (lMax - lMin) * (DATA.plotBottom - DATA.plotTop);

  /* Y axis: grid lines and tick labels. */
  const axis = document.getElementById("y-axis");
  while (axis.firstChild) axis.removeChild(axis.firstChild);
  for (const v of ticks(axMin, axMax)) {
    const y = mapY(v);
    const line = document.createElementNS(NS, "line");
    line.setAttribute("x1", DATA.plotLeft); line.setAttribute("x2", DATA.plotRight);
    line.setAttribute("y1", y.toFixed(2)); line.setAttribute("y2", y.toFixed(2));
    line.setAttribute("class", "grid");
    axis.appendChild(line);
    const t = document.createElementNS(NS, "text");
    t.setAttribute("x", (DATA.plotLeft - 10).toFixed(1)); t.setAttribute("y", (y + 3.5).toFixed(2));
    t.setAttribute("class", "tick-label"); t.setAttribute("text-anchor", "end");
    t.textContent = fmtTick(v);
    axis.appendChild(t);
  }

  /* Each series: band, median line, dots, value labels. */
  DATA.series.forEach((s, i) => {
    const g = document.getElementById("series-" + i);
    g.setAttribute("data-on", on[i] ? "true" : "false");
    if (!on[i]) return;
    const X = DATA.x;
    let band = "";
    X.forEach((x, k) => { band += (k ? " L " : "M ") + x + " " + mapY(s.max[k]).toFixed(2); });
    for (let k = X.length - 1; k >= 0; k--) band += " L " + X[k] + " " + mapY(s.min[k]).toFixed(2);
    g.querySelector(".band").setAttribute("d", band + " Z");
    let med = "";
    X.forEach((x, k) => { med += (k ? " L " : "M ") + x + " " + mapY(s.med[k]).toFixed(2); });
    g.querySelector(".median").setAttribute("d", med);
    g.querySelectorAll(".dot").forEach(dot => {
      const k = +dot.getAttribute("data-size");
      dot.setAttribute("cy", mapY(s.med[k]).toFixed(2));
    });
    g.querySelectorAll(".value-label").forEach(t => {
      const k = +t.getAttribute("data-size");
      t.setAttribute("y", (mapY(s.med[k]) + +t.getAttribute("data-offset")).toFixed(2));
    });
  });

  /*
   * Right-edge labels. Visible ones sit at their last-size median, pushed
   * apart by labelGap. Hidden ones park in a compact dimmed row below.
   * The whole stack then shifts up as needed so it ends inside the plot.
   */
  const last = DATA.x.length - 1;
  const slots = visible.map(i => [i, mapY(DATA.series[i].med[last])]).sort((a, b) => a[1] - b[1]);
  for (let k = 1; k < slots.length; k++) {
    slots[k][1] = Math.max(slots[k][1], slots[k - 1][1] + DATA.labelGap);
  }
  let parkY = slots.length ? slots[slots.length - 1][1] + 30 : DATA.plotTop + 20;
  const hidden = DATA.series.map((_, i) => i).filter(i => !on[i]);
  for (const i of hidden) { slots.push([i, parkY]); parkY += DATA.parkGap; }
  const bottom = slots[slots.length - 1][1] + (hidden.length ? 6 : 20);
  const shift = Math.max(0, bottom - DATA.plotBottom);
  for (const [i, y] of slots) {
    const lab = document.getElementById("series-" + i).querySelector(".series-label");
    lab.setAttribute("transform", `translate(0 ${(y - shift).toFixed(2)})`);
  }

  /* Elbow annotation follows the baseline's first dot. */
  const elbow = document.getElementById("elbow");
  const b = DATA.series[DATA.baseline];
  elbow.setAttribute("transform", `translate(${DATA.x[0]} ${mapY(b.med[0]).toFixed(2)})`);
  elbow.style.display = on[DATA.baseline] ? "" : "none";

  /* Provenance: visible contenders' lines close ranks after the shared lines. */
  let slot = DATA.sharedProv;
  DATA.series.forEach((s, i) => {
    document.getElementById("series-" + i).querySelectorAll(".series-prov").forEach(t => {
      if (on[i]) t.setAttribute("y", (DATA.provTop + 40 + slot++ * DATA.provLine).toFixed(1));
    });
  });

  document.getElementById("takeaway").textContent = takeaway();
}

function toggleSeries(i) {
  on[i] = !on[i];
  relayout();
}
window.toggleSeries = toggleSeries;
